-- Generated by airbnb_etl.ddl. Do not edit by hand.
-- Refresh with: python -m airbnb_etl.ddl
--
-- Inside Airbnb city snapshot. listings is the analytical projection of the
-- detailed gzip extract (descriptions, photo URLs, and host essays stay out).
-- calendars is the high-volume table and stays narrow: stay date, availability,
-- and night bounds. reviews holds comment text. review_dates is the summary
-- file, a date spine with no comment body.
-- Fact tables have no foreign keys. A multi-gigabyte COPY should not pay for
-- a referential check on every calendar or review row.

IF OBJECT_ID(N'dbo.markets', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.markets (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  name NVARCHAR(256) NOT NULL,
  country NVARCHAR(64) NOT NULL,
  region NVARCHAR(64) NOT NULL,
  city NVARCHAR(64) NOT NULL,
  loaded_at DATETIME2 NULL,
  CONSTRAINT pk_markets PRIMARY KEY CLUSTERED (market_code, snapshot_date)
  );
END;

IF OBJECT_ID(N'dbo.pipeline_runs', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.pipeline_runs (
  run_id NVARCHAR(36) NOT NULL,
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  status NVARCHAR(32) NOT NULL,
  dry_run BIT NOT NULL,
  started_at DATETIME2 NULL,
  finished_at DATETIME2 NULL,
  error_message NVARCHAR(MAX) NULL,
  stats NVARCHAR(MAX) NULL,
  CONSTRAINT pk_pipeline_runs PRIMARY KEY CLUSTERED (run_id)
  );
END;

IF OBJECT_ID(N'dbo.dataset_files', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.dataset_files (
  run_id NVARCHAR(36) NOT NULL,
  dataset_name NVARCHAR(64) NOT NULL,
  source_url NVARCHAR(MAX) NOT NULL,
  storage_key NVARCHAR(MAX) NOT NULL,
  byte_size BIGINT NOT NULL,
  sha256 NVARCHAR(64) NOT NULL,
  row_count BIGINT NOT NULL,
  rejected_count INT NOT NULL,
  elapsed_ms INT NOT NULL,
  reused BIT NOT NULL,
  CONSTRAINT pk_dataset_files PRIMARY KEY CLUSTERED (run_id, dataset_name),
  CONSTRAINT fk_dataset_files_run FOREIGN KEY (run_id) REFERENCES pipeline_runs(run_id)
  );
END;

IF OBJECT_ID(N'dbo.listings', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.listings (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  listing_id BIGINT NOT NULL,
  name NVARCHAR(512) NULL,
  host_id BIGINT NULL,
  host_name NVARCHAR(256) NULL,
  host_since DATE NULL,
  host_is_superhost BIT NULL,
  host_listings_count INT NULL,
  host_identity_verified BIT NULL,
  host_response_rate DECIMAL(6,2) NULL,
  host_acceptance_rate DECIMAL(6,2) NULL,
  neighbourhood NVARCHAR(256) NULL,
  neighbourhood_cleansed NVARCHAR(256) NULL,
  neighbourhood_group NVARCHAR(256) NULL,
  latitude DECIMAL(9,6) NULL,
  longitude DECIMAL(9,6) NULL,
  property_type NVARCHAR(128) NULL,
  room_type NVARCHAR(128) NULL,
  accommodates INT NULL,
  bathrooms DECIMAL(4,1) NULL,
  bedrooms INT NULL,
  beds INT NULL,
  amenities NVARCHAR(MAX) NULL,
  price DECIMAL(14,2) NULL,
  price_quote_total DECIMAL(14,2) NULL,
  price_quote_per_night DECIMAL(14,2) NULL,
  minimum_nights INT NULL,
  maximum_nights INT NULL,
  has_availability BIT NULL,
  availability_30 INT NULL,
  availability_365 INT NULL,
  number_of_reviews INT NULL,
  number_of_reviews_ltm INT NULL,
  number_of_reviews_l30d INT NULL,
  first_review DATE NULL,
  last_review DATE NULL,
  review_scores_rating DECIMAL(5,2) NULL,
  review_scores_accuracy DECIMAL(5,2) NULL,
  review_scores_cleanliness DECIMAL(5,2) NULL,
  review_scores_checkin DECIMAL(5,2) NULL,
  review_scores_communication DECIMAL(5,2) NULL,
  review_scores_location DECIMAL(5,2) NULL,
  review_scores_value DECIMAL(5,2) NULL,
  estimated_occupancy_l365d DECIMAL(10,2) NULL,
  estimated_revenue_l365d DECIMAL(14,2) NULL,
  instant_bookable BIT NULL,
  reviews_per_month DECIMAL(6,2) NULL,
  license NVARCHAR(256) NULL,
  CONSTRAINT pk_listings PRIMARY KEY CLUSTERED (market_code, snapshot_date, listing_id)
  );
END;

IF OBJECT_ID(N'dbo.listing_summaries', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.listing_summaries (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  listing_id BIGINT NOT NULL,
  name NVARCHAR(512) NULL,
