  host_profile_id NVARCHAR(256) NULL,
  host_name NVARCHAR(256) NULL,
  neighbourhood_group NVARCHAR(256) NULL,
  neighbourhood NVARCHAR(256) NULL,
  latitude DECIMAL(9,6) NULL,
  longitude DECIMAL(9,6) NULL,
  room_type NVARCHAR(128) NULL,
  price DECIMAL(14,2) NULL,
  minimum_nights INT NULL,
  number_of_reviews INT NULL,
  last_review DATE NULL,
  reviews_per_month DECIMAL(6,2) NULL,
  calculated_host_listings_count INT NULL,
  availability_365 INT NULL,
  number_of_reviews_ltm INT NULL,
  license NVARCHAR(256) NULL,
  CONSTRAINT pk_listing_summaries PRIMARY KEY CLUSTERED (market_code, snapshot_date, listing_id)
  );
END;

IF OBJECT_ID(N'dbo.calendars', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.calendars (
  market_code NVARCHAR(64) NOT NULL,
