  available BIT NULL,
  minimum_nights INT NULL,
  maximum_nights INT NULL,
  CONSTRAINT pk_calendars PRIMARY KEY CLUSTERED (market_code, snapshot_date, listing_id, stay_date)
  );
END;

IF OBJECT_ID(N'dbo.reviews', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.reviews (
