  snapshot_date DATE NOT NULL,
  review_id BIGINT NOT NULL,
  listing_id BIGINT NOT NULL,
  review_date DATE NULL,
  reviewer_id BIGINT NULL,
  reviewer_name NVARCHAR(256) NULL,
  comments NVARCHAR(MAX) NULL,
  CONSTRAINT pk_reviews PRIMARY KEY CLUSTERED (market_code, snapshot_date, review_id)
  );
END;

IF OBJECT_ID(N'dbo.review_dates', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.review_dates (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  source_row INT NOT NULL,
  listing_id BIGINT NOT NULL,
  review_date DATE NOT NULL,
  CONSTRAINT pk_review_dates PRIMARY KEY CLUSTERED (market_code, snapshot_date, source_row)
  );
END;

IF OBJECT_ID(N'dbo.neighbourhoods', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.neighbourhoods (
