IF OBJECT_ID(N'dbo.neighbourhood_geometries', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.neighbourhood_geometries (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  neighbourhood NVARCHAR(256) NOT NULL,
  neighbourhood_group NVARCHAR(256) NULL,
  geometry NVARCHAR(MAX) NULL,
  CONSTRAINT pk_neighbourhood_geometries PRIMARY KEY CLUSTERED (market_code, snapshot_date, neighbourhood)
  );
