IF OBJECT_ID(N'dbo.neighbourhood_metrics', N'U') IS NULL
BEGIN
  CREATE TABLE dbo.neighbourhood_metrics (
  market_code NVARCHAR(64) NOT NULL,
  snapshot_date DATE NOT NULL,
  neighbourhood NVARCHAR(256) NOT NULL,
  listings INT NOT NULL,
  median_price DECIMAL(14,2) NULL,
  avg_price DECIMAL(14,2) NULL,
  avg_rating DECIMAL(5,2) NULL,
  superhost_share DECIMAL(7,4) NULL,
  avg_availability_365 DECIMAL(8,2) NULL,
  estimated_revenue DECIMAL(16,2) NULL,
  avg_occupancy DECIMAL(10,2) NULL,
  CONSTRAINT pk_neighbourhood_metrics PRIMARY KEY CLUSTERED (market_code, snapshot_date, neighbourhood)
  );
END;

IF NOT EXISTS (
  SELECT 1 FROM sys.indexes
  WHERE name = N'ix_listings_room' AND object_id = OBJECT_ID(N'dbo.listings')
)
BEGIN
  CREATE INDEX ix_listings_room ON dbo.listings (market_code, snapshot_date, room_type);
END;

IF NOT EXISTS (
  SELECT 1 FROM sys.indexes
  WHERE name = N'ix_listings_price' AND object_id = OBJECT_ID(N'dbo.listings')
)
BEGIN
  CREATE INDEX ix_listings_price ON dbo.listings (market_code, snapshot_date, price);
END;

IF NOT EXISTS (
  SELECT 1 FROM sys.indexes
  WHERE name = N'ix_listings_neighbourhood' AND object_id = OBJECT_ID(N'dbo.listings')
)
BEGIN
  CREATE INDEX ix_listings_neighbourhood ON dbo.listings (market_code, snapshot_date, neighbourhood_cleansed);
END;

IF NOT EXISTS (
  SELECT 1 FROM sys.indexes
  WHERE name = N'ix_reviews_listing' AND object_id = OBJECT_ID(N'dbo.reviews')
)
BEGIN
  CREATE INDEX ix_reviews_listing ON dbo.reviews (market_code, snapshot_date, listing_id, review_date);
END;

IF NOT EXISTS (
  SELECT 1 FROM sys.indexes
  WHERE name = N'ix_review_dates_listing' AND object_id = OBJECT_ID(N'dbo.review_dates')
)
BEGIN
  CREATE INDEX ix_review_dates_listing ON dbo.review_dates (market_code, snapshot_date, listing_id, review_date);
END;

GO

CREATE OR ALTER VIEW dbo.market_metrics AS
SELECT
  market_code,
  snapshot_date,
  COUNT(*) AS listings,
  AVG(price) AS avg_price,
  AVG(review_scores_rating) AS avg_rating,
  AVG(CASE WHEN host_is_superhost = 1 THEN 1.0 WHEN host_is_superhost = 0 THEN 0.0 END) AS superhost_share,
  SUM(estimated_revenue_l365d) AS estimated_revenue,
  AVG(estimated_occupancy_l365d) AS avg_occupancy,
  AVG(availability_365) AS avg_availability_365
FROM listings
GROUP BY market_code, snapshot_date;
